#include <iostream>
#include <cmath>

struct EconomyBalance {
    // Player earns this many coins per hour of play
    float coinsPerHour = 1000.0f;

    // How much things cost at each level
    float getUpgradeCost(int level) const {
        // Exponential curve: costs increase as you level up
        return 100.0f * std::pow(1.5f, level);
    }

    // How many hours to afford the next upgrade
    float hoursToNextUpgrade(int currentLevel) const {
        float cost = getUpgradeCost(currentLevel + 1);
        return cost / coinsPerHour;
    }

    // XP required for each level (S-curve)
    int xpForLevel(int level) const {
        // Early levels: fast. Mid levels: slower. Late levels: very slow
        if (level < 10) return 100 * level;           // 100, 200, 300...
        if (level < 30) return 1000 + 200 * (level - 10);  // 1000, 1200...
        return 5000 + 500 * (level - 30);              // 5000, 5500...
    }

    // Total XP to reach a level
    int totalXpToReachLevel(int targetLevel) const {
        int total = 0;
        for (int i = 1; i < targetLevel; ++i)
            total += xpForLevel(i);
        return total;
    }

    void printBalanceReport(int maxLevel = 50) {
        std::cout << "=== ECONOMY BALANCE REPORT ===\n\n";
        std::cout << "Level | XP to next | Total XP | Upgrade Cost | Hours to grind\n";
        std::cout << "------|------------|----------|--------------|----------------\n";

        for (int level = 1; level <= maxLevel; level += 5) {
            int xpNext = xpForLevel(level);
            int totalXp = totalXpToReachLevel(level);
            float upgradeCost = getUpgradeCost(level);
            float hours = hoursToNextUpgrade(level);

            std::cout << level << "     | " << xpNext << "         | " 
                      << totalXp << "       | " << upgradeCost << "          | "
                      << hours << "h\n";
        }

        // Check for balance issues
        std::cout << "\n=== BALANCE CHECKS ===\n";
        float timeToMaxLevel = 0;
        for (int i = 1; i < maxLevel; ++i) {
            // Assuming 500 XP per hour from gameplay
            timeToMaxLevel += xpForLevel(i) / 500.0f;
        }
        std::cout << "Time to reach max level: " << timeToMaxLevel << " hours\n";
        std::cout << (timeToMaxLevel > 40 && timeToMaxLevel < 200 
                     ? "BALANCE OK" : "ADJUST XP CURVE");
        std::cout << "\n";
    }
};

int main() {
    EconomyBalance economy;
    economy.printBalanceReport();
    return 0;
}
